crlb-study.inputs_code:
# Exponential with mean 2, estimated by the sample mean: I(m) = 1/m^2,
# so the floor is m^2/n and this estimator sits exactly on it. A study
# needs no family, only something to draw with and something to run.
def sampler(n, rng):
    return rng.exponential(2.0, n)
def estimator(y):
    return float(np.mean(y))
inputs = (sampler, estimator, 2.0, 0.25, 30, 500, 99)
